\begin{theorem}\label{thm:main}
There exists a three-dimensional complete Noetherian normal local domain
$R$ containing $\C$, with residue field $\C$, such that no nonzero finitely
generated $R$-module has depth three.
\end{theorem}

\begin{theorem}\label{thm:obstruction}
Let $X$ be a smooth integral projective surface over $\C$, and let $H$ be
an ample globally generated divisor. If $R(X,H)$ admits a small
Cohen--Macaulay module, then
\begin{equation}\label{eq:obstruction}
 K_X^2-2c_2(X)\leq 6H^2.
\end{equation}
\end{theorem}

\begin{lemma}[The left nullspace]
\label{lem:hub-nullspace}
The left nullspace of the limiting matrix in
Lemma~\ref{lem:limiting-columns}, including its curve column,
has dimension \(g\). Its projection to the old blocks identifies
it with \(\mathcal G\): for each \(c\in\mathcal G\), its leaf
weights are \(c_{i,h}\) on every row \((i,h,j)\), independently
of \(j\), and its hub weights are the uniquely determined
compatible functionals. Consequently
\begin{equation}
 \sum_i\sum_{h\in I_i}c_{i,h}\operatorname{tr}(B_{i,h})=0
 \qquad(c\in\mathcal G).
 \label{eq:error-matrix-trace}
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:symbol-division}
The central simple algebra $A\otimes_k B_n$ is division.  Its pure
rational scalar extensions and its central Laurent series extensions
are division as well.
\end{lemma}

\begin{lemma}\label{lem:nonconstant-roots}
For $n\ge n_0$, every distinct generic eigenvalue of $W(P)$ has a
nonzero differential in the input entries.  Independent small generic
points of sizes at least $n_0$ have disjoint spectra.  Their spectra
also avoid the constant spectrum of $w(0)$.
\end{lemma}

\begin{lemma}\label{lem:stable-multiplicity}
For every $N\ge1$,
\[
 t_{pN}=t,\qquad e_{pN}=Ne_p.
\]
\end{lemma}

\begin{lemma}[An inverse between two vanishing couplings]
\label{lem:killed-pole}
Let $E$ be a field and let $M(\xi)\in\operatorname{End}_E(V)[[\xi]]$, where
$V$ is finite dimensional.  Suppose that zero is a semisimple eigenvalue of
$M_0=M(0)$, and let $\Pi$ be its spectral projection.  Suppose that
\[
 G=\Pi M'(0)\Pi\big|_{\ker M_0}
\]
is invertible.  Then $M(\xi)^{-1}$ exists over $E((\xi))$ and has a pole of
order at most one.  Let $J$ be zero on $\ker M_0$ and equal to $M_0^{-1}$ on
$\operatorname{im}M_0$.  If $L(\xi)$ and $B(\xi)$ are compatible matrix
series satisfying
\[
 L(0)\Pi=0,\qquad \Pi B(0)=0,
\]
then
\begin{equation}
\label{eq:killed-pole-limit}
 \lim_{\xi\to0}L(\xi)M(\xi)^{-1}B(\xi)=L(0)JB(0).
\end{equation}

Suppose additionally that $e$ is an idempotent, $f=1-e$,
$fM_0f$ is invertible on $fV$, and $e:\ker M_0\to eV$ is an isomorphism.
Under the same two coupling conditions,
\begin{equation}
\label{eq:fixed-complement-inverse}
 L(0)JB(0)=L(0)f(fM_0f)^{-1}fB(0).
\end{equation}
\end{lemma}

\begin{theorem}\label{thm:main}
A countable discrete group is strongly Ulam stable if and only if it is
amenable.
\end{theorem}

\begin{lemma}[Sparse restrictions]\label{lem:sparse}
For every $0<\eta<1/4$ there is $0<\beta_0<1/16$ with the following property.
If $0<\beta\leq\beta_0$, then for every sufficiently large integer $m$
there are unit vectors $(a_x)_{x\in X}$ in $\mathbb R^m$, where
$|X|=2m$, and signs $f(x)\in\{1,-1\}$ such that:
\begin{enumerate}
\item the vectors with either sign form an orthonormal basis, and hence
\begin{equation}\label{eq:frame-cancellation}
 \sum_{x\in X} f(x)a_xa_x^*=0;
\end{equation}
\item if $S\subseteq X$ and $|S|\leq4\beta|X|$, the synthesis map
$F_S:\ell^2(S)\to\mathbb C^m$, $F_Se_x=a_x$, satisfies
\begin{equation}\label{eq:sparse-gram}
 \norm{F_S^*F_S-\id}\leq\eta.
\end{equation}
\end{enumerate}
Moreover, for every sufficiently large integer $n$ there is a real
orthogonal $n\times n$ matrix $O$ such that, on a set $Y$ of size $2n$,
\begin{equation}\label{eq:JZ}
 J=\begin{pmatrix}0&O\\ O^*&0\end{pmatrix},
 \qquad Z=\begin{pmatrix}\id&0\\0&-\id\end{pmatrix}
\end{equation}
satisfy
\begin{equation}\label{eq:sparse-J}
 \norm{P_SJP_T}\leq\eta
 \quad\text{whenever}\quad |S|,|T|\leq4\beta|Y|.
\end{equation}
In particular, $J^*=J$, $J^2=Z^2=\id$, $JZ=-ZJ$, and every diagonal
entry of $J$ is zero.
\end{lemma}

\begin{proposition}\label{prop:comparison}
There are numerical constants $C$ and $h_0>0$ such that, for the construction
of Section~\ref{sec:construction} with $h\le h_0$ and $0<\eta\le1/4$,
\begin{equation}\label{eq:comparison}
 \norm{V_{qp}^{\{p,q\}}-V_{qp}^{\{p,q,r\}}}
 \le Ch+CN\eta+CNh\eta
\end{equation}
for every three configurations $p,q,r$. The constants do not depend on
the cardinalities of any alphabets or on the configurations.
\end{proposition}

\begin{lemma}\label{lem:transport}
For all but a proportion $2N\beta$ of labels $i\in\cI$,
\begin{equation}\label{eq:transport-bound}
 \norm{\mu(s_i)u_i-r_i}\le CN\eta+CNh\eta.
\end{equation}
\end{lemma}

\begin{proposition}\label{prop:sparse-splitting}
Let \(G\) be countable and nonamenable, and fix \(S,d,\rho\) as in
\Cref{lem:contracting-average}. For every \(\ell\ge1\), list the products
of \(\ell\) elements of \(S\), with multiplicity, as
\(s_1,\ldots,s_n\), where \(n=d^\ell\), and put
\(r=\lceil n\rho^\ell\rceil\). There is a function
\(a:G\times\{1,\ldots,n\}\to\{0,1\}\) such that
\begin{equation}\label{eq:sparse-mask}
 \#\{i:a(x,i)=1\}\le r\quad(x\in G),\qquad
 \#\{i:a(ys_i^{-1},i)=0\}\le r\quad(y\in G).
\end{equation}
\end{proposition}

\begin{proposition}[Uniformly bounded conjugation differences]
\label{prop:uniform-differences}
Under \Cref{eq:weights-orientation-bounds}, the maps $U(g)$ in
\Cref{eq:weights-A-T-U} form a unitary representation of $G$,
and $A$ commutes with every $U(g)$.  Define
\[
 D(g)=T-U(g)TU(g)^{-1}\quad(g\in G).
\]
Then
\begin{equation}
\label{eq:uniform-difference-bound}
 \sup_{g\in G}\norm{D(g)}\le b_0^2=100.
\end{equation}
Moreover, $D(e)=0$ and
\begin{equation}
\label{eq:weights-cocycle}
 D(gh)=D(g)+U(g)D(h)U(g)^{-1}\quad(g,h\in G).
\end{equation}
\end{proposition}
